  return `<section class="ui-screen ui-main" data-screen="main"><div class="ui-brand"><span class="ui-kicker">Arcade mini golf</span><h1>${GAME_CONFIG.title}</h1><p>Master impossible greens. Outsmart rivals. Own the arena.</p></div><nav class="ui-menu" aria-label="Main menu">${button('Play', 'play', true)}${button('Custom Game', 'custom')}${button('Ranked', 'ranked')}${button('Profile', 'profile')}${button('Settings', 'settings')}</nav><aside class="ui-player-chip"><span class="ui-avatar">${esc(model.profile.displayName).slice(0,1)}</span><span><strong>${esc(model.profile.displayName)}</strong><small>Lv. ${model.profile.level} · ${model.profile.rating} rating</small></span></aside></section>`;
}

function setup(title: string, kicker: string, mode: 'play'|'custom'|'ranked', model: UIModel): string {
