}
export const renderPlay = (m:UIModel) => setup('Play','Quick match','play',m);
export const renderCustom = (m:UIModel) => setup('Custom Game','Build your match','custom',m);
export const renderRanked = (m:UIModel) => setup('Ranked','Competitive arena','ranked',m);

export function renderSettings(settings: UISettings): string {
 const range=(key:string,label:string,value:number)=>`<label class="ui-field"><span>${label}<output>${value}</output></span><input data-setting="${key}" type="range" min="0" max="100" value="${value}"></label>`;
 return `<section class="ui-screen" data-screen="settings">${header('Settings','Tune your game')}<div class="ui-grid"><div class="ui-panel"><h2>Controls</h2><label class="ui-field"><span>Shot controls</span><select data-setting="controlScheme"><option value="drag-power" ${settings.controlScheme==='drag-power'?'selected':''}>Drag for power</option><option value="hold-to-charge" ${settings.controlScheme==='hold-to-charge'?'selected':''}>Hold to charge</option></select></label>${range('cameraSensitivity','Camera sensitivity',settings.cameraSensitivity)}<label class="ui-toggle"><input data-setting="reducedMotion" type="checkbox" ${settings.reducedMotion?'checked':''}><span>Reduced camera motion</span></label></div><div class="ui-panel"><h2>Audio</h2>${range('masterVolume','Master',settings.masterVolume)}${range('musicVolume','Music',settings.musicVolume)}${range('effectsVolume','Effects',settings.effectsVolume)}</div></div></section>`;
