import { DEFAULT_UI_MODEL } from './mockData';
import { renderCustom, renderMainMenu, renderPlay, renderProfile, renderRanked, renderSettings } from './screens';
import type { UIAction, UIModel, UIScreen, UISettings } from './types';
import './ui.css';

export class UIRoot {
  private screen: UIScreen = 'main';
  constructor(private readonly root: HTMLElement, private model: UIModel = DEFAULT_UI_MODEL, private readonly onAction: (action:UIAction)=>void = ()=>{}) { this.render(); }
  navigate(screen: UIScreen) { this.screen = screen; this.onAction({type:'navigate',screen}); this.render(); }
  private render() {
    const views = { main:()=>renderMainMenu(this.model), play:()=>renderPlay(this.model), custom:()=>renderCustom(this.model), ranked:()=>renderRanked(this.model), settings:()=>renderSettings(this.model.settings), profile:()=>renderProfile(this.model.profile) };
    this.root.innerHTML = `<div class="ui-shell">${views[this.screen]()}</div>`;
    this.bind();
  }
  private bind() {
    this.root.querySelectorAll<HTMLElement>('[data-nav]').forEach(el=>el.addEventListener('click',()=>this.navigate(el.dataset.nav as UIScreen)));
    this.root.querySelector<HTMLElement>('[data-start]')?.addEventListener('click', e=>{
      const target=e.currentTarget as HTMLElement; const course=this.root.querySelector<HTMLInputElement>('input[name="course"]:checked')?.value ?? this.model.courses[0]?.id ?? '';
      const players=Number(this.root.querySelector<HTMLSelectElement>('[data-field="players"]')?.value ?? 1);
      this.onAction({type:'start-match',mode:target.dataset.start as 'play'|'custom'|'ranked',courseId:course,players});
    });
    this.root.querySelectorAll<HTMLInputElement|HTMLSelectElement>('[data-setting]').forEach(el=>el.addEventListener('change',()=>{
      const next={...this.model.settings}; const key=el.dataset.setting as keyof UISettings;
      if(key==='reducedMotion') next[key]=(el as HTMLInputElement).checked;
      else if(key==='controlScheme') next[key]=(el as HTMLSelectElement).value as UISettings['controlScheme'];
      else (next as unknown as Record<string,number>)[key]=Number(el.value);
      this.model={...this.model,settings:next}; this.onAction({type:'settings-changed',settings:next});
    }));
  }
}
